def choose_move(observation):
    def clamp_step(a, b):
        if b > a:
            return 1
        if b < a:
            return -1
        return 0

    def manhattan(p, q):
        return abs(p[0] - q[0]) + abs(p[1] - q[1])

    def safe_pos(value, default=(0, 0)):
        if isinstance(value, (list, tuple)) and len(value) >= 2:
            return value[0], value[1]
        return default

    def best_by_distance(items, origin, want_max=False):
        best = None
        best_key = None
        for item in items or []:
            pos = safe_pos(item, None)
            if pos is None:
                continue
            d = manhattan(pos, origin)
            key = (-d if want_max else d, pos[0], pos[1])
            if best is None or key < best_key:
                best = pos
                best_key = key
        return best

    env = observation.get("environment_name", "resource_collection")
    sx, sy = safe_pos(observation.get("self_position"), (0, 0))
    ox, oy = safe_pos(observation.get("opponent_position"), (sx, sy))
    role = observation.get("self_role", "pursuer")

    if env == "pursuit_evasion":
        if role == "pursuer":
            return [clamp_step(sx, ox), clamp_step(sy, oy)]
