        gh = observation.get("grid_height", 0)
        if gw and gh:
            center = ((gw - 1) // 2, (gh - 1) // 2)
            return [clamp_step(sx, center[0]), clamp_step(sy, center[1])]
        return [0, 0]

    resources = observation.get("resources") or observation.get("resource_positions") or []
    best = best_by_distance(resources, (sx, sy), want_max=False)
    if best is not None:
        dx = clamp_step(sx, best[0])
        dy = clamp_step(sy, best[1])
        opp_dist = manhattan((sx, sy), (ox, oy))
